24	struct cfl_array *cfl_array_create(size_t slot_count)
25	{
26	    struct cfl_array *array;
27	
28	    array = malloc(sizeof(struct cfl_array));
29	    if (array == NULL) {
30	        cfl_errno();
31	        return NULL;
32	    }
33	
34	    /* by default arrays are not resizable */
35	    array->resizable = CFL_FALSE;
36	
37	    /* allocate fixed number of entries */
38	    array->entries = calloc(slot_count, sizeof(void *));
39	    if (array->entries == NULL) {
40	        cfl_errno();
41	        free(array);
42	        return NULL;
43	    }
44	
45	    array->entry_count = 0;
46	    array->slot_count = slot_count;
47	
48	    return array;
49	}
50	
51	void cfl_array_destroy(struct cfl_array *array)
52	{
53	    size_t index;
54	
55	    if (!array) {
56	        return;
57	    }
58	
59	    if (array->entries != NULL) {
60	        for (index = 0 ; index < array->entry_count ; index++) {
61	            if(array->entries[index] != NULL) {
62	                cfl_variant_destroy(array->entries[index]);
63	            }
64	        }
65	
66	        free(array->entries);
67	    }
68	    free(array);
69	}
70	
71	int cfl_array_resizable(struct cfl_array *array, int v)
72	{
73	    if (v != CFL_TRUE && v != CFL_FALSE) {
74	        return -1;
75	    }
76	
77	    array->resizable = v;
78	    return 0;
79	}
80	
81	int cfl_array_remove_by_index(struct cfl_array *array,
82	                              size_t position)
83	{
84	    if (position >= array->entry_count) {
85	        return -1;
86	    }
87	
88	    cfl_variant_destroy(array->entries[position]);
89	
90	    if (position != array->entry_count - 1) {
91	        memmove(&array->entries[position],
92	                &array->entries[position + 1],
93	                sizeof(void *) * (array->entry_count - (position + 1)));
94	    }
95	    else {
96	        array->entries[position] = NULL;
97	    }
98	    array->entry_count--;
99	
100	    return 0;
101	}
102	
103	int cfl_array_remove_by_reference(struct cfl_array *array,
104	                                  struct cfl_variant *value)
105	{
106	    size_t index;
107	
108	    for (index = 0 ; index < array->entry_count ; index++) {
109	        if (array->entries[index] == value) {
110	            return cfl_array_remove_by_index(array, index);
111	        }
112	    }
113	
114	    return 0;
115	}
116	
117	int cfl_array_append(struct cfl_array *array,
118	                     struct cfl_variant *value)
119	{
120	    void *tmp;
121	    size_t new_slot_count;
122	    size_t new_size;
123	
124	    if (array->entry_count >= array->slot_count) {
125	        /*
126	         * if there is no more space but the caller allowed to resize
127	         * the array, just double the size. Yeah, this is scary and should
128	         * be used only when the caller 'knows this is safe to do' because
129	         * it controls the input data.
130	         */
131	        if (array->resizable) {
132	            /* set new number of slots and total size */
133	            new_slot_count = (array->slot_count * 2);
134	            new_size = (new_slot_count * sizeof(void *));
135	
136	            tmp = realloc(array->entries, new_size);
137	            if (!tmp) {
138	                cfl_report_runtime_error();
139	                return -1;
140	            }
141	            array->slot_count = new_slot_count;
142	            array->entries = tmp;
143	        }
144	        else {
145	            return -1;
146	        }
147	    }
148	    array->entries[array->entry_count++] = value;
149	
150	    return 0;
151	}
