/*
 * This interface is a minimized version of Fluent Bit SDS just for easily
 * string storage
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>
#include <inttypes.h>

#include <cfl/cfl_sds.h>

size_t cfl_sds_avail(cfl_sds_t s)
{
    struct cfl_sds *h;

    h = CFL_SDS_HEADER(s);
    return (size_t) (h->alloc - h->len);
}

cfl_sds_t sds_alloc(size_t size)
{
    void *buf;
    cfl_sds_t s;
    struct cfl_sds *head;

    buf = malloc(CFL_SDS_HEADER_SIZE + size + 1);
    if (!buf) {
        return NULL;
    }

    head = buf;
    head->len = 0;
    head->alloc = size;

    s = head->buf;
    *s = '\0';

    return s;
}

size_t cfl_sds_alloc(cfl_sds_t s)
{
    return (size_t) CFL_SDS_HEADER(s)->alloc;
}

cfl_sds_t cfl_sds_increase(cfl_sds_t s, size_t len)
{
    size_t new_size;
    struct cfl_sds *head;
    cfl_sds_t out;
