size_t cfl_sds_avail(cfl_sds_t s)
{
    struct cfl_sds *h;

    h = CFL_SDS_HEADER(s);
    return (size_t) (h->alloc - h->len);
}

cfl_sds_t sds_alloc(size_t size)
{
    void *buf;
    cfl_sds_t s;
    struct cfl_sds *head;

    buf = malloc(CFL_SDS_HEADER_SIZE + size + 1);
    if (!buf) {
        return NULL;
    }

    head = buf;
    head->len = 0;
    head->alloc = size;

    s = head->buf;
    *s = '\0';

    return s;
}

size_t cfl_sds_alloc(cfl_sds_t s)
{
    return (size_t) CFL_SDS_HEADER(s)->alloc;
}

