{
    size_t new_size;
    struct cfl_sds *head;
    cfl_sds_t out;
    void *tmp;

    out = s;
    new_size = (CFL_SDS_HEADER_SIZE + cfl_sds_alloc(s) + len + 1);
    head = CFL_SDS_HEADER(s);
    tmp = realloc(head, new_size);
