Here are the three requested functions from the source.

## cfl_variant_create_from_string_s

```c
struct cfl_variant *cfl_variant_create_from_string_s(char *value, size_t value_size, int referenced)
{
    struct cfl_variant *instance;

    if (value == NULL && value_size > 0) {
        return NULL;
    }

    instance = cfl_variant_create();
    if (!instance) {
        return NULL;
    }
    instance->referenced = referenced ? CFL_TRUE : CFL_FALSE;

    if (referenced) {
        instance->data.as_string = value;
    }
    else {
        if (value_size > INT_MAX) {
            free(instance);
            return NULL;
        }

        instance->data.as_string = cfl_sds_create_len(value, (int) value_size);
        if (instance->data.as_string == NULL) {
            free(instance);
            return NULL;
        }

    }
    cfl_variant_size_set(instance, value_size);
    instance->type = CFL_VARIANT_STRING;

    return instance;
}
```

## cfl_variant_create_from_bytes

```c
struct cfl_variant *cfl_variant_create_from_bytes(char *value, size_t length, int referenced)
{
    struct cfl_variant *instance;

    if (value == NULL && length > 0) {
        return NULL;
    }

    instance = cfl_variant_create();
    if (!instance){
        return NULL;
    }
    instance->referenced = referenced ? CFL_TRUE : CFL_FALSE;

    if (referenced) {
        instance->data.as_bytes = value;
    }
    else {
        if (length > INT_MAX) {
            free(instance);
            return NULL;
        }

        instance->data.as_bytes = cfl_sds_create_len(value, (int) length);
        if (instance->data.as_bytes == NULL) {
            free(instance);
            return NULL;
        }
    }
    cfl_variant_size_set(instance, length);
    instance->type = CFL_VARIANT_BYTES;

    return instance;
}
```

## cfl_variant_destroy

```c
void cfl_variant_destroy(struct cfl_variant *instance)
{
    if (!instance) {
        return;
    }

    cfl_container_release_variant(instance);

    if (instance->type == CFL_VARIANT_STRING ||
        instance->type == CFL_VARIANT_BYTES) {
        if (instance->data.as_string != NULL && !instance->referenced) {
            cfl_sds_destroy(instance->data.as_string);
        }
    }
    else if (instance->type == CFL_VARIANT_ARRAY) {
        cfl_array_destroy(instance->data.as_array);
    }
    else if (instance->type == CFL_VARIANT_KVLIST) {
        cfl_kvlist_destroy(instance->data.as_kvlist);
    }

    free(instance);
}
```

## How the `referenced` parameter is handled

In both creation functions, the flag is normalized and stored on the instance via `instance->referenced = referenced ? CFL_TRUE : CFL_FALSE;`. 

- When **referenced is true**, the pointer is stored directly (`instance->data.as_string = value;` or `instance->data.as_bytes = value;`) with no copy made — the variant borrows the caller's memory.
- When **referenced is false**, a new owned copy is allocated with `cfl_sds_create_len(...)`, after first rejecting sizes exceeding `INT_MAX`.

In `cfl_variant_destroy`, the flag governs cleanup: for string/bytes types, the data is freed via `cfl_sds_destroy` only when `!instance->referenced` — so borrowed (referenced) buffers are left untouched, avoiding freeing memory the variant doesn't own.

