+    TEST_CHECK(ret == 0);
+
+    cfl_array_destroy(arr);
+}
+
+static void append_bytes_ref()
+{
+    int ret;
+    char *buf;
+    struct cfl_array *arr;
+
+    buf = malloc(5);
